#include "sculpt-scene-chunks.hpp"
#include "sculpt-placed-chunks.hpp"
#include "dome/source-placement.hpp"
#include <nlohmann/json.hpp>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace dome;using namespace dome::detail;
namespace {
Volume sphere(){constexpr float voxel=.0125f,radius=.6f;const float band=voxel*4;const int n=int(std::ceil((radius+band)/voxel));Volume::Voxels values;for(int z=-n;z<=n;++z)for(int y=-n;y<=n;++y)for(int x=-n;x<=n;++x){const float distance=length(Vec3{x*voxel,y*voxel,z*voxel})-radius;if(distance<band){if(values.size()>=4'000'000)throw std::runtime_error("Original sphere sample guard reached");values.emplace(Int3{x,y,z},std::max(-band,distance));}}return Volume::from_samples(voxel,std::move(values));}
nlohmann::json describe(const Scene&s,const SculptSceneChunks::Ptr&p){nlohmann::json objects=nlohmann::json::array();size_t triangles=0;for(const auto&o:p->objects()){triangles+=o.geometry->report().indices/3;objects.push_back({{"id",o.object},{"geometry_bytes",o.geometry->report().retained_bytes},{"placed_bytes",o.placed?o.placed->placement_bytes():0},{"triangles",o.geometry->report().indices/3},{"samples",s.object(o.object).volume->voxels().size()},{"kind",int(o.geometry->report().kind)}});}return{{"retained_bytes",p->retained_bytes()},{"triangles",triangles},{"objects",objects}};}
}
int main(int argc,char**argv){if(argc!=2)return 2;const std::filesystem::path out=argv[1];std::filesystem::create_directories(out);nlohmann::json result{{"source","f5998a1824a86f259ffbb31174bcd32244f3d8c1"},{"voxel",.0125},{"radius",.6},{"objects",4},{"retained_limit",512*1024*1024},{"working_limit",1024*1024*1024},{"phases",nlohmann::json::array()}};int code=1;try{Scene scene;const auto base=sphere();scene.active().volume=std::make_shared<Volume>(base);for(int i=1;i<4;++i){CanvasTransform pose;pose.position={1.3f*i,0,0};scene.add("Independent authored sphere "+std::to_string(i+1),base,pose);}scene.object(4).affine_edit=std::make_shared<NativeAffineEdit>(AffineTransform(std::array<double,16>{-1,0,0,0,.17,1.1,0,0,.07,.09,.85,0,0,0,0,1}));scene.select(1);auto frame=SculptSceneChunks::capture(scene,{8191,1,1,true,true}).chunks;result["phases"].push_back(describe(scene,frame));std::cout<<"INITIAL "<<result["phases"].back()<<std::endl;constexpr Vec3 points[]{{.55f,0,0},{0,.55f,0},{0,0,.55f},{-.55f,0,0}};for(int i=0;i<4;++i){const uint64_t id=i+1;result["phase"]="independent edit "+std::to_string(id);scene.select(id);auto &v=*scene.object(id).volume;const auto old=v.geometry_owner();Brush b;b.from=b.to=points[i];b.normal=normalized(points[i]);b.radius=.12f;b.strength=.75f;b.blend=.1f;b.tool=Tool::Clay;v.begin_stroke();v.stamp(b);if(!v.end_stroke()||v.geometry_owner()==old)throw std::runtime_error("Independent object stroke did no geometry work");auto next=SculptSceneChunks::capture(scene,{8191,uint64_t(i+2),1,true,true},frame).chunks;frame=std::move(next);auto record=describe(scene,frame);record["edited_object"]=id;result["phases"].push_back(record);std::cout<<"EDIT "<<record<<std::endl;}result["success"]=true;code=0;}catch(const std::exception&e){result["error"]=e.what();std::cerr<<"FAIL "<<result["phase"]<<' '<<e.what()<<std::endl;}result["exit"]=code;std::ofstream file(out/"result.json");file<<result.dump(2)<<'\n';return code;}
